// For large crates we prevent `MethodTooLargeException` (see #2340)
// N.B. the name of the extension is very misleading, since it is
// rather `InterfaceTooLargeException`, caused by too many methods
// in the interface for large crates.
//
// By splitting the otherwise huge interface into two parts
// * UniffiLib
// * IntegrityCheckingUniffiLib (this)
// we allow for ~2x as many methods in the UniffiLib interface.
//
// The `ffi_uniffi_contract_version` method and all checksum methods are put
// into `IntegrityCheckingUniffiLib` and these methods are called only once,
// when the library is loaded.
internal interface IntegrityCheckingUniffiLib : Library {
    // Integrity check functions only
    fun uniffi_rust_lib_bluebubbles_checksum_func_complete_message(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_create_login_session(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_do_lock(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_finish_unlock(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_get_carrier(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_has_hardware_config(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_has_saved_users(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_init_native(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_is_locked(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_mark_journal_attempt(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_parse_call_poster(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_parse_poster(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_provision_from_encoded(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_provision_from_relay(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_provision_from_validation_data(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_ptr_to_message(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_read_queued_journal(
): Short
fun uniffi_rust_lib_bluebubbles_checksum_func_recover_keychain(
): Short
